from taf.sbts.oam.coam.admin.interfaces.admin_24r3 import SBTS24R3
from taf.sbts.oam.coam.admin.schemas.procedure.ccm_uplink_pusch_25r1 import CCMUplinkPusch
from taf.sbts.oam.coam.admin.schemas.procedure.ccm_uplink_prach_25r1 import CCMUplinkPrach
from taf.sbts.oam.coam.admin.exceptions import DataNotAvailable


class SBTS25R1(SBTS24R3):

    def __init__(self,
                 api_client=None
                 ):
        """
        :param api_client: instance of an AdminApi class
        """
        super(SBTS25R1, self).__init__(api_client)

    def start_5g_uplink_ccm_test_pusch(self, dist_name, interval, beam_pattern_id,
                                       frc_index, prb_offset, digital_out_type,
                                       digital_out_rate, ul_dmrs_mapping_type, is_ptrs_fr2_enabled,
                                       ru_mode, phys_cell_id,
                                       bb_selector=None, nrarfcn_ul=None, nrarfcn_dl=None, num_uci_bits=None,
                                       csi_payload_bit=None, act_high_speed_cell=None, digital_output_enable=None,
                                       timeout=60):
        """
        Starts 5G `Pusch` Performance CCM Test (start5GUplinkCCMTest).

        :param str dist_name: `NRCELL_R` object to perform the test on.
        :param float interval: Reporting time interval [0.1..3600] (step 0.1)
        :param List[int] beam_pattern_id: [0..1200].
        :param str frc_index: One of the following:
                                'G_FR1_A3_8' | 'G_FR1_A3_9' | 'G_FR1_A3_10' | 'G_FR1_A3_12' | 'G_FR1_A3_13' | 'G_FR1_A3_14' |
                                'G_FR1_A3_22' | 'G_FR1_A3_23' | 'G_FR1_A3_24' | 'G_FR1_A3_26' | 'G_FR1_A3_27' | 'G_FR1_A3_28' |
                                'G_FR1_A3_31' | 'G_FR1_A3_32' | 'G_FR1_A4_8' | 'G_FR1_A4_9' | 'G_FR1_A4_10' | G_FR1_A4_11 |
                                'G_FR1_A4_12' | 'G_FR1_A4_13' | 'G_FR1_A4_14' | 'G_FR1_A4_22' | 'G_FR1_A4_23' | 'G_FR1_A4_24' |
                                'G_FR1_A4_26' | 'G_FR1_A4_27' | 'G_FR1_A4_28' | 'G_FR1_A5_8' | 'G_FR1_A5_9' | 'G_FR1_A5_10' |
                                'G_FR1_A5_12' | 'G_FR1_A5_13' | 'G_FR1_A5_14' | 'G_FR2_A3_4' | 'G_FR2_A3_9' | 'G_FR2_A3_16' |
                                'G_FR2_A3_21' | 'G_FR2_A4_4' | 'G_FR2_A4_9' | 'G_FR2_A4_14' | 'G_FR2_A4_19' | 'G_FR2_A5_4' |
                                'G_FR2_A5_9' | 'G_FR1_A1_2' | 'G_FR1_A1_5' | 'G_FR1_A2_5' | 'G_FR1_A1_1' | 'G_FR1_A1_4' |
                                'G_FR1_A2_4' | 'G_FR1_A4_31' | 'G_FR1_A4_31A' | 'G_FR1_A4_32' | 'G_FR1_A4_32A' |
                                'G_FR1_A3_34' | 'G_FR1_A4_30' | 'G_FR2_A7_4' | 'G_FR2_A7_9' | 'G_FR1_A3_34A' | 'G_FR1_A4_30A'
                                'G_FR1_A3_11'| 'G_FR1_A3_25'| 'G_FR1_A4_25'| 'G_FR1_A5_11' | 'G_FR1_A2_2' |
                                'G_FR1_A9_1' | 'G_FR1_A9_2' | 'G_FR1_A9_3' | 'G_FR1_A9_4' | 'G_FR1_A9_5' | 'G_FR2_A4_3' |
                                'G_FR2_A4_13' | 'G_FR1_A4_29' | 'G_FR1_A4_29A' | 'G_FR1_A3_33' | 'G_FR1_A3_33A'
        :param int prb_offset: [0..273].
        :param str digital_out_type: Either `SerialKeysight` or `SerialRs`.
        :param str digital_out_rate: Either `Bitrate_115dot2K`,
                                     `Bitrate_1dot92M` or `Bitrate_460dot8K`.
        :param str ul_dmrs_mapping_type: "A" or "B".
        :param bool is_ptrs_fr2_enabled.
        :param str ru_mode: One of the following:
                            `NR_Only`, `MSR` (`MSR` is supported when RU contains EUTRA.Frequency.Band)
        :param int phys_cell_id: [0..1007].
        :param bool act_high_speed_cell: (optional) Activate high speed cell.
        :param bool digital_output_enable: Enable digital output.
        :param int bb_selector: (Optional) [0..3].
        :param int nrarfcn_ul: (Optional) [0..3279165].
        :param int nrarfcn_dl: (Optional) [0..3279165].
        :param int num_uci_bits: (Optional) [0.255].
        :param list[int] csi_payload_bit: (Optional, two items at most) list of integers [0..4294967295]
        :param int timeout: (optional) Timeout for the operation.
        :return: It returns dict with data.

        Example response

        ::
            {
                "indicationDistName": "/MRBTS-1/RAT-1/URI-1/SESSION-13/START_NR_UPLINKCCM_TEST_IND-0",
                "confirmationNode": {
                    "distName": "/MRBTS-1/RAT-1/URI-1/SESSION-13/START_NR_UPLINKCCM_TEST_IND-0/ACK-1",
                    "parameters": {}
                },
                "resultNode": {
                    "distName": "/MRBTS-1/RAT-1/URI-1/SESSION-13/START_NR_UPLINKCCM_TEST_IND-0/NR_TEST_RESULT-1",
                    "parameters": {
                        "status": "Succeeded"
                    }
                }
            }

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-start5GUplinkCCMTest.html

        """
        if not isinstance(is_ptrs_fr2_enabled, bool):
            raise ValueError('Parameter is_ptrs_fr2_enabled should be bool True or False not {}'
                             .format(type(is_ptrs_fr2_enabled)))
        if not isinstance(act_high_speed_cell, (bool, type(None))):
            raise ValueError('Parameter act_high_speed_cell should be bool True or False not {}'
                             .format(type(act_high_speed_cell)))
        if not isinstance(digital_output_enable, bool):
            raise ValueError('Parameter digital_output_enable should be bool True or False not {}'
                             .format(type(digital_output_enable)))

        PERFORMANCE_TEST_TYPE = "Pusch"
        pusch_schema = CCMUplinkPusch(nrcell_rdn=dist_name, nrarfcn_ul=nrarfcn_ul, reporting_time_interval=interval,
                                      beam_pattern_id=beam_pattern_id, performance_test_type=PERFORMANCE_TEST_TYPE,
                                      frc_index=frc_index, prb_offset=prb_offset, digital_out_type=digital_out_type,
                                      digital_out_rate=digital_out_rate, ul_dmrs_mapping_type=ul_dmrs_mapping_type,
                                      is_ptrs_fr2_enabled=is_ptrs_fr2_enabled, ru_mode=ru_mode,
                                      phys_cell_id=phys_cell_id, bb_selector=bb_selector, nrarfcn_dl=nrarfcn_dl,
                                      num_uci_bits=num_uci_bits, csi_payload_bit=csi_payload_bit,
                                      act_high_speed_cell=act_high_speed_cell, digital_output_enable=digital_output_enable)
        parameters = pusch_schema.as_dict()

        return self._api_client.execute_procedure('start5GUplinkCCMTest',
                                                  parameters, timeout)

    def reset_site(self, timeout=300, wait_for_reconnection=True, detailed_output=False, graceful_cell_shutdown=None,
                   reset_without_ru=None):
        """
        Preform site reset procedure.

        :param int timeout: Timeout for the operation.
        :param bool wait_for_reconnection: True/False if we should wait for OAM Node-B reconnection
                    (Default: True, as in legacy siteReset admin-cli command).
        :param bool detailed_output: return full request response when True, defaults set to False.
        :param bool graceful_cell_shutdown: (Optional) - Defaults to False, it is not applicable to ALD/GNSSE/GNSSI.
        :param bool reset_without_ru: Optional - default value: false) //Added since CB012446-B.
        :return str: Site reset status. Examples of returned statuses: "ongoing", "completed", "failed".

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-reset.html
        """
        request_parameters = {"waitForReconnection": wait_for_reconnection, "resetCoverage": "Site"}

        if graceful_cell_shutdown is not None:
            request_parameters['gracefulCellShutdown'] = graceful_cell_shutdown

        if reset_without_ru is not None:
            request_parameters["siteResetWithoutRuReset"] = reset_without_ru

        response = self._api_client.execute_customer_procedure("reset", request_parameters, timeout)
        if response is None:
            raise DataNotAvailable("Site reset status has not been provided by M-Plane.")
        return response if detailed_output else response.get(self._provided_content.request_message)

    def get_account_status_report(self, timeout=60, detailed_output=False):
        """
        Acquires account status report.

        :param int timeout: Timeout for the operation, 60 second by default.
        :param bool detailed_output: return full request response when True, defaults set to False.
        :return Union[str,dict]: Result operation result as string ie. Completed, Failed, sometimes empty or full response dict.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-getAccountStatusReport.html
        """
        response = self._api_client.execute_customer_procedure("getAccountStatusReport", {}, timeout)
        return response if detailed_output else response.get(self._provided_content.request_message)

    def get_sw_version_status(self, timeout=60, detailed_output=False):
        """
        Retrieves SW version status.

        :param int timeout: Timeout for the operation, 60 second by default.
        :param bool detailed_output: return full request response when True, defaults set to False.
        :return Union[str,dict]: Result operation result as string ie. Completed, Failed, sometimes empty or full response dict.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-getSwVersionStatus.html
        """
        response = self._api_client.execute_customer_procedure("getSwVersionStatus", {}, timeout)
        return response if detailed_output else response.get(self._provided_content.request_message)

    def _validation_5g_downlink_parameters(self, params):
        test_model = (params['test_model'] in ("TM1_1", "TM1_2", "TM2", "TM2A", "TM3_1",
                                               "TM3_1A", "TM3_2", "TM3_3", "TM3_1N", "TM1_1_ETSI", "IdleActive"))
        beam_pattern_id = (all(item >= 0 and item <= 1200 for item in params['beam_pattern_id']))
        polarization = (params['polarization'] in ("P_plus45_or_0", "P_minus45_or_90", "P_both"))
        power_backoff = (0 <= params['power_backoff'] <= 490)
        ru_mode = (params['ru_mode'] in ("NR_Only", "MSR", "Customize_1"))
        phys_cell_id = (0 <= params['phys_cell_id'] <= 1007)
        p_max = (params['p_max'] is None or (0 <= params['p_max'] <= 49))
        nrarfcn_dl = (params['nrarfcn_dl'] is None or (0 <= params['nrarfcn_dl'] <= 3279165))
        nrarfcn_ul = (params['nrarfcn_ul'] is None or (0 <= params['nrarfcn_ul'] <= 3279165))
        i11_codebook_4_antports = (0 <= params['i11_codebook_4_antports'] <= 7)
        i2_codebook_4_antports = (0 <= params['i2_codebook_4_antports'] <= 3)
        codebook_2_antports = (0 <= params['codebook_2_antports'] <= 3)
        i13_codebook_4_antports = (0 <= params['i13_codebook_4_antports'] <= 1)
        mimo_rank = (1 <= params['mimo_rank'] <= 2)
        load_type = (params['load_type'] in ("flatLoad", "burstLoad", "slotWiseLoad", None))
        load_level_flat = (params['load_level_flat'] in ("low", "medium", "busy", "full", None))
        load_level_burst = (params['load_level_burst'] in ("burst_13_5", "burst_19_2", "burst_32_7", "burst_46_2", "burst_59_6",
                                                           "burst_73_1", "burst_86_5", "burst_100", None))
        load_level_slot_wise = (params['load_level_slot_wise'] in ('load_0_low', 'load_10', 'load_30_medium', 'load_50_busy_hour', 'load_70', None))
        num_of_ssb_beam_pattern_id = (params['num_of_ssb_beam_pattern_id'] in ("ssb_1", "ssb_4", "ssb_8", "ssb_32", None))

        params_to_check = {'test_model': test_model, 'beam_pattern_id': beam_pattern_id, 'polarization': polarization,
                           'power_backoff': power_backoff, 'ru_mode': ru_mode, 'phys_cell_id': phys_cell_id,
                           'i11_codebook_4_antports': i11_codebook_4_antports,
                           'i2_codebook_4_antports': i2_codebook_4_antports, 'mimo_rank': mimo_rank,
                           'p_max': p_max, 'nrarfcn_dl': nrarfcn_dl, 'nrarfcn_ul': nrarfcn_ul,
                           'codebook_2_antports': codebook_2_antports,
                           'i13_codebook_4_antports': i13_codebook_4_antports, 'load_type': load_type,
                           'load_level_flat': load_level_flat, 'load_level_burst': load_level_burst,
                           'load_level_slot_wise': load_level_slot_wise,
                           'num_of_ssb_beam_pattern_id': num_of_ssb_beam_pattern_id}

        self._check_parameters(params_to_check, params, "tutorial-start5GDownlinkTest.html")

    def start_5g_downlink_test(self, dist_name, test_model, beam_pattern_id,
                               polarization, power_backoff, ru_mode, phys_cell_id,
                               codebook_2_antports, i11_codebook_4_antports, i2_codebook_4_antports,
                               i13_codebook_4_antports, mimo_rank, p_max=None, nrarfcn_dl=None, nrarfcn_ul=None,
                               timeout=60, load_type=None, load_level_flat=None, load_level_burst=None,
                               load_level_slot_wise=None, num_of_ssb_beam_pattern_id=None, ssb_beam_pattern_id=None,
                               vswr_monitoring=None, act_micro_dtx=None):
        """
        Starts 5G Downlink Test.

        :param str dist_name: `NRCELL_R` object to perform the test on.
        :param str test_model: One of the following: `TM1_1`, `TM1_2`, `TM2`,
                               `TM2A`, `TM3_1`, `TM3_1A`, `TM3_2`, `TM3_3`, `TM3_1N`, 'TM1_1_ETSI', 'IdleActive'.
        :param List[int] beam_pattern_id: [0..1200].
        :param str polarization: One of the following: `P_plus45_or_0`,
                                 `P_minus45_or_90`, `P_both`.
        :param int power_backoff: [0..490].
        :param str ru_mode: One of the following:
                            `NR_Only`, `MSR`, 'Customize_1' (`MSR` is supported when RU contains EUTRA.Frequency.Band)
        :param int phys_cell_id: [0..1007].
        :param int codebook_2_antports: [0..3]. [0,1,2,3] are supported when mimoRank is set to 1, [0,1,2] are
                                        supported when mimoRank is set to 2
        :param int i11_codebook_4_antports: [0..7].
        :param int i2_codebook_4_antports: [0..3].
                  ( i2Codebook4AntPorts should be 0 if "polarization" is set to P_plus45_or_0.)
        :param int i13_codebook_4_antports: [0..1]. ( i13_codebook_4_antports should be 0 if mimoRank is set to 1.)
        :param int mimo_rank: [1..2]
        :param int p_max: (Optional) [0..60].
        :param int nrarfcn_dl: (Optional) [0..3279165].
        :param int nrarfcn_ul: (Optional) [0..3279165].
        :param int timeout: (optional) Timeout for the operation.
        :param str load_type: "flatLoad" | "burstLoad" | "slotWiseLoad" required only when TM1_1_ETSI is set for test_model
        :param str load_level_flat:  "low" | "medium" | "busy" | "full" (required only when "flatLoad" set for "load_type")
        :param str load_level_burst: "burst_13_5" | "burst_19_2" | "burst_32_7" | "burst_46_2" | "burst_59_6" |
                                    "burst_73_1" | "burst_86_5" | "burst_100" (required only when "burstLoad" set for "load_type")
        :param str load_level_slot_wise: 'load_0_low' | 'load_10' | 'load_30_medium'| 'load_50_busy_hour' | 'load_70'. Required only
                                       when load_level set for loadLevelSlotWise.
        :param str num_of_ssb_beam_pattern_id: "ssb_1", "ssb_4" | "ssb_8" | "ssb_32" (required only when "low" set for "load_level_flat".
                                        ssb_4 when FR1<=3GHz ssb_8 when 3 GHz<FR1<6 GHz ssb_32 when FR2. Note: 1 GHz = 1000 MHz)
        :param list ssb_beam_pattern_id: array of integer <0 to 1200>  (items number: 4, 8, 32 depends on value of "num_of_ssb_beam_pattern_id")
        :param boolean vswr_monitoring: Optional, default set to false.
        :param boolean act_micro_dtx: Optional, default set to true.

        :return: It returns dict with data.

        Example response

        ::

            {
              "indicationDistName": "/MRBTS-1/RAT-1/URI-1/SESSION-13/START_NR_DOWNLINK_TEST_IND-0",
              "confirmationNode": {
                 "distName": "/MRBTS-1/RAT-1/URI-1/SESSION-13/START_NR_DOWNLINK_TEST_IND-0/ACK-1",
                 "parameters": {}
              },
              "resultNode": {
                 "distName": "/MRBTS-1/RAT-1/URI-1/SESSION-13/START_NR_DOWNLINK_TEST_IND-0/NR_TEST_RESULT-1",
                 "parameters": {
                    "status": "Succeeded"
                 }
              }
            }

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-start5GDownlinkTest.html

        """

        params_to_check = {'test_model': test_model, 'beam_pattern_id': beam_pattern_id, 'polarization': polarization,
                           'power_backoff': power_backoff, 'p_max': p_max, 'nrarfcn_dl': nrarfcn_dl,
                           'nrarfcn_ul': nrarfcn_ul, 'ru_mode': ru_mode, 'phys_cell_id': phys_cell_id,
                           'i11_codebook_4_antports': i11_codebook_4_antports,
                           'i2_codebook_4_antports': i2_codebook_4_antports,
                           'codebook_2_antports': codebook_2_antports,
                           'i13_codebook_4_antports': i13_codebook_4_antports, 'mimo_rank': mimo_rank,
                           'load_type': load_type, 'load_level_flat': load_level_flat,
                           'load_level_burst': load_level_burst, 'load_level_slot_wise': load_level_slot_wise,
                           'num_of_ssb_beam_pattern_id': num_of_ssb_beam_pattern_id}

        self._validation_5g_downlink_parameters(params_to_check)

        power_measure_config = {'loadType': load_type, 'loadLevelFlat': load_level_flat,
                                'loadLevelBurst': load_level_burst,
                                'loadLevelSlotWise': load_level_slot_wise,
                                'numOfSsbBeamPatternId': num_of_ssb_beam_pattern_id,
                                'ssbBeamPatternId': ssb_beam_pattern_id}
        power_measure_config = {k: v for k, v in power_measure_config.items() if v}

        parameters = {
            'nrcell_rDN': dist_name,
            'params': {
                "testModel": test_model,
                "beamPatternId": beam_pattern_id,
                "polarization": polarization,
                "powerBackoff": power_backoff,
                "pMax": p_max,
                "nrarfcnDl": nrarfcn_dl,
                "nrarfcnUl": nrarfcn_ul,
                "ruMode": ru_mode,
                "physCellId": phys_cell_id,
                "codebook2AntPorts": codebook_2_antports,
                "codebook4AntPorts": {"i11Codebook4AntPorts": i11_codebook_4_antports,
                                      "i2Codebook4AntPorts": i2_codebook_4_antports,
                                      "i13Codebook4AntPorts": i13_codebook_4_antports},
                "mimoRank": mimo_rank
            },
        }
        parameters['params'] = {k: v for k, v in parameters['params'].items() if v is not None}

        if power_measure_config:
            parameters['params']['powerMeasureConfig'] = power_measure_config

        if vswr_monitoring is not None:
            parameters['params']['vswrMonitoring'] = vswr_monitoring

        if act_micro_dtx is not None:
            parameters['params']['actMicroDtx'] = act_micro_dtx

        return self._api_client.execute_procedure('start5GDownlinkTest', parameters, timeout)

    def start_5g_uplink_ccm_test_prach(self, dist_name, interval,
                                       beam_pattern_id, receiving_slot,
                                       expectation_slot,
                                       preamble_index, accepted_timing_error,
                                       constant_offset,
                                       delay_pattern_single_step_duration,
                                       ru_mode, phys_cell_id,
                                       prach_configuration_index,
                                       pfa_target_prach_id,
                                       nrarfcn_ul=None, nrarfcn_dl=None,
                                       timeout=60, prach_root_sequence_index=None,
                                       zero_correlation_zone_config=None,
                                       prach_sequence_type=None,
                                       act_high_speed_cell=None,
                                       digital_output_enable=None,
                                       act_prach_format_c2_with_scs=None):
        """
        Starts 5G `Prach` Performance CCM Test (start5GUplinkCCMTest).

        :param str dist_name: `NRCELL_R` object to perform the test on.
        :param float interval: Reporting time interval [0.1..3600] (step 0.1)
        :param List[int] beam_pattern_id: [0..1200].
        :param int receiving_slot: [0..1023].
        :param int expectation_slot: [0..1023].
        :param int preamble_index: [0..63].
        :param int accepted_timing_error: [0..999999].
        :param int constant_offset: [0..999999].
        :param int delay_pattern_single_step_duration: [0..1000].
        :param str ru_mode: One of the following:
                            `NR_Only`, `MSR` (`MSR` is supported when RU contains EUTRA.Frequency.Band)
        :param int phys_cell_id: [0..1007].
        :param bool act_high_speed_cell: (optional) Activate high speed cell.
        :param bool digital_output_enable: Enable digital output.
        :param int prach_configuration_index: [0..255]
        :param str pfa_target_prach_id: Either 'P_None', 'P_01', 'P_001', 'P_0005', 'P_0001', 'P_005', 'P_05' or 'P_10'
        :param int nrarfcn_ul: (Optional) [0..3279165].
        :param int nrarfcn_dl: (Optional) [0..3279165].
        :param Union[int,str] timeout: (optional) Timeout for the operation.
        :param int prach_root_sequence_index: [0..837].
        :param int zero_correlation_zone_config: [0..15].
        :param str prach_sequence_type: PRACH sequence type ["Unrestricted" | "RestrictedTypeA" | "RestrictedTypeB"]
        :param bool act_prach_format_c2_with_scs: (optional) Activate PRACH format C2 with SCS 15kHz. [True, False]
        :return: It returns dict with data.

        Example response

        ::

            {
              "indicationDistName": "/MRBTS-1/RAT-1/URI-1/SESSION-13/START_NR_UPLINKCCM_TEST_IND-0",
              "confirmationNode": {
                 "distName": "/MRBTS-1/RAT-1/URI-1/SESSION-13/START_NR_UPLINKCCM_TEST_IND-0/ACK-1",
                 "parameters": {}
              },
              "resultNode": {
                 "distName": "/MRBTS-1/RAT-1/URI-1/SESSION-13/START_NR_UPLINKCCM_TEST_IND-0/NR_TEST_RESULT-1",
                 "parameters": {
                    "status": "Succeeded"
                 }
              }
           }

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-start5GUplinkCCMTest.html

        """

