    def generate_nokia_compliant_orusw_package(self, sw_package, target_file_name=None, timeout=300):
        """
        Generate Nokia compliant O-RU software package.

        :param str sw_package: The file path of the original O-RU package.
        :param str target_file_name: (Optional) Name of the output software package.
        :param int timeout: Time to wait for positive procedure result.
        :return Union[str,dict]: Result operation result as string ie. Completed, Failed, sometimes empty or full response dict.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-generateNokiaCompliantORUSWPackage.html
        """
        if target_file_name is None:
            return self._api_client.execute_customer_procedure("generateNokiaCompliantORUSWPackage",
                                                               {"inputFilesContent": sw_package}, timeout)
        else:
            return self._api_client.execute_customer_procedure("generateNokiaCompliantORUSWPackage",
                                                               {"inputFilesContent": sw_package,
                                                                "outputFileName": target_file_name}, timeout)
